    lessonPlan: '0–5 تهيئة: ثلاث بدايات جمل على السبورة، والثنائيات تحدّد نوع المعلومة وتتوقّع جملة لكل بداية؛ 5–12 استماع والكتب مغلقة مع كتابة الأسماء، ثم قراءة صامتة وتأطير تعريف العقيدة التوحيدية؛ 12–19 شجرة النسب: مجموعات رباعية ترسم خطّي إسماعيل وإسحاق على ورقة، وتتبادلها مع مجموعة مجاورة لتحذف كل سهم لا يذكره النص (يعقوب جدٌّ لموسى وعيسى لا أبوهما)؛ 19–22 قراءة جهرية مضبوطة لجمل المجهول الأربع في ثنائيات؛ 22–25 التحدي السريع فرديًّا؛ 25–33 التركيز اللغوي: النشاط 1 اكتشافًا جماعيًّا (مَن أطلق اللقب؟ ماذا صار في مركز الجملة؟)، والنشاطان 2–3 في ثنائيات مع متابعة المعلم لرفع نائب الفاعل؛ 33–38 استعمال: يكتب المتعلمون أول أربع جمل من فقرة النشاط 4 عن عالِم أو شاعر أو شخصية محلية، ويقرأ متطوعان ويحدّد الصف «بوصفه» والفعل المبني للمجهول؛ 38–40 بطاقة الخروج',
    discussionPoints: ['أيّ الجمل تنقل كيف يقدّم القرآن الكريم إبراهيم، وأيّها تعطي معلومة نسب مباشرة؟', 'لماذا يؤكّد الفصل أن لقب «خليل الله» لم يُمنح لأيّ نبي قبله؟ وماذا يضيف المجهول إلى هذا التأكيد؟', 'ما الادعاء غير المدعوم الذي قد يقوله قارئ متسرّع عن الديانات الثلاث؟'],
    interactiveTips: ['استخدم نقطة «رسول التوحيد» للتحقق من التعريف المؤطَّر، ونقطة «أبو الأنبياء» لمناقشة نسب الأنبياء قبل الحديث عن الديانات الثلاث.', 'أعد تشغيل جمل النسب ببطء، ودع المتعلمين يصحّحون الشجرة أثناء الاستماع.', 'أعد تشغيل «كما أُطلِقَ على إبراهيم عليه السلام لقبٌ فريدٌ» واسأل: ما علامة «لقبٌ»؟ ولماذا؟', 'عامِل سطر «الكلمات المفتاحية» في أول الفصل دعمًا للمفردات لا جزءًا من السرد.'],
    differentiation: { strugglingLearners: 'وزّع بطاقات أسماء (إبراهيم، إسماعيل، إسحاق، يعقوب، محمد صلى الله عليه وسلم، يوسف، موسى، هارون، يونس، عيسى) لبناء الشجرة قبل الكتابة، وإطارين مشكولين: «يُقَدَّمُ ____ بوصفه ____» و«____ تعني أنْ ____».', fastFinishers: 'اكتب جملتين عن جائزة أو لقب حقيقي: واحدة مبنية للمعلوم تذكر الفاعل وأخرى مبنية للمجهول، ثم اشرح في جملة ثالثة ما الذي صار في مركز كل جملة.' },
    formativeAssessment: ['يعيد بناء خطّي النسب من غير روابط مخترعة.', 'يشرح أن «يُقدَّم… بوصفه» تسمّي مصدرًا ولا تعبّر عن شك.', 'يرفع نائب الفاعل وينصب المفعول به عند التحويل إلى المعلوم.'],
    expectedResponses: ['يُقدَّم إبراهيم عليه السلام في القرآن الكريم بوصفه رسولَ التوحيد وداعيه وممثّله، وهو الشخصية الأساسية في اليهودية والمسيحية والإسلام، وأبو النبيّين إسماعيل وإسحاق، وقد أُطلِق عليه لقبُ «خليل الله» الذي لم يُمنح لأيّ نبي قبله.'],
