    assessmentTools: { rubric: ['دقة النسب', 'تأطير المصدر', 'التعريف والإضافة', 'المبني للمجهول ونائب الفاعل'], exitTicket: ['أكمل واضبط: «يُقَدَّمُ ____ في ____ بوصفه ____»، ثم حوّل «أَطْلَقَ الناسُ على المدينة اسمًا جديدًا» إلى المبني للمجهول.'] },
