    afterReading: ['أنجز التحدي السريع واذكر الجملة التي تدعم إجابتك.', 'التركيز اللغوي: مطابقة المصطلحات (النشاط 1)، وتحديد موقف الكاتب (النشاط 2)، ثم إعادة صياغة السبب والقصر (النشاط 3).', 'اكتب فقرة النشاط 4 عن تقليد أو نظام له أصل ثابت وتفاصيل متغيّرة.'],
    lessonPlan: '0–5 تهيئة: أربع كلمات على السبورة، وكل ثنائية تكتب سؤال توقّع يربط كلمتين؛ 5–11 استماع للمهمة والاختبارات، ثم قراءة صامتة وتأطير التعريفين؛ 11–18 شبكة المفاهيم: ترسم الثنائيات أسهمًا بين الحنيف والحنيفية والعقل والعبادات، وعلى كل سهم عبارة مقتبسة، ثم مراجعة سريعة لأسئلة التوقّع؛ 18–21 قراءة جهرية مضبوطة للجمل الثلاث الأخيرة مع كسر همزة «إنّ» بعد القول؛ 21–24 التحدي السريع؛ 24–32 التركيز اللغوي: النشاط 1 في ثنائيات، والنشاط 2 اكتشافًا جماعيًّا (أيّ الجملتين تعريف وأيّهما رأي الكاتب؟)، والنشاط 3 فرديًّا ثم مراجعة ثنائية مع تعليل نصب «قدراتِ» بعد «لأنّ»؛ 32–38 استعمال: يخطّط المتعلمون فقرة النشاط 4 بمنظّم من أربع خانات (تعريف / موقف / «أي إنّ» / سبب ← استنتاج) عن رياضة أو لغة أو تقليد مدرسي ويكتبون أول خمس جمل؛ 38–40 بطاقة الخروج',
    discussionPoints: ['أيّ الجمل تعريفات، وأيّ جملة يقدّمها الكاتب استنتاجًا حذرًا؟', 'بحسب الفصل، ما الذي يستطيع الإنسان الوصول إليه بالعقل والتفكير؟', 'ما الذي يحصره الفصل في العبادات بالضبط؟ وماذا تفعل «فقط» هناك؟'],
    interactiveTips: ['استخدم نقطة «مهمّة حياته» للفقرة الأولى، ونقطة «الطريق الحنيف» لإكمال تعريف الحنيف.', 'أعد تشغيل «ويُمكِننا القول إنّها…» وجملة «أي إنّ…» واسأل: ماذا تفعل كل منهما؟', 'لا توسّع المقارنة بين الأديان خارج جمل الفصل.'],
    differentiation: { strugglingLearners: 'قدّم إطارات مشكولة: «الحنيفُ هو الموحِّدُ الذي ____»، «والحنيفيّةُ هي ____»، «يُمكِننا القولُ إنّ ____»، «____، أيْ إنّ ____»، مع جمل الفصل مقطّعة شرائط للمطابقة.', fastFinishers: 'اكتب فقرة تجمع تعريفًا مباشرًا بـ«هو/هي» واستنتاجًا حذرًا واضح الوسم، ثم ضع بجانب كل جملة «تعريف» أو «استنتاج» وعلّل.' },
