    assessmentTools: { rubric: ['الملاحظة والدليل', 'الإمكان والقدرة', '«كأنّ» والتحوّل', 'الموصول والنصب'], exitTicket: ['اكتب جملة بـ«كأنّ» وأخرى بـ«قادر على» + مصدر عن موقف في مدرستك.'] },
