    afterReading: ['أنجز التحدي السريع مع الرجوع إلى الصوتين والجدول.', 'التركيز اللغوي: فرز التهديد والالتزام (النشاط 1)، ثم الغاية بالمصدر والفعل (النشاط 2)، ثم «قد» ولام التعليل و«منعه من» (النشاط 3).', 'اكتب فقرة النشاط 4 عن عمل صعب يستمر رغم العواقب.'],
    lessonPlan: '0–4 تهيئة: لماذا يسأل الطبيب والمعلم؟ والثنائيات تكتب جملتين بلام التعليل؛ 4–10 قراءة نموذجية للآيات مرتين، ثم فرز العبارات بين صوت الأب وصوت إبراهيم على السبورة؛ 10–15 استماع لفقرة الكاتب وقراءة صامتة مع سؤال: ماذا قرّر إبراهيم رغم قسوة أبيه؟؛ 15–20 جدول التشبيه: مجموعات ثلاثية تملأ الأعمدة الثلاثة بعبارات مقتبسة، وتقرأ الجملة الطويلة قراءة جهرية مضبوطة بوقفة قبل «كان إبراهيم»؛ 20–23 التحدي السريع؛ 23–31 التركيز اللغوي: النشاط 1 في ثنائيات مع تعليل شفهي، والنشاط 2 سباق تحويل بين صفّين (مصدر ↔ فعل)، والنشاط 3 فرديًّا مع سؤال: هل العواقب مؤكّدة؟؛ 31–38 استعمال: فقرة النشاط 4 عن صحفي أو عالم أو متطوع يواصل عمله رغم صعوبته، فيها «قد + مضارع» وتشبيه «كما… أو كما…» وغاية بالمصدر؛ 38–40 بطاقة الخروج',
    discussionPoints: ['كيف يختلف ردّ إبراهيم عن كلام أبيه في الآيات؟', 'ماذا يضيف تشبيه الطبيب والقاضي إلى فهم أسئلة إبراهيم؟', 'لماذا يهمّ أن الكاتب يقول إن إبراهيم كان يعلم أنه «قد» يواجه عواقب سلبية؟'],
    interactiveTips: ['استخدم نقطة «تهديد الأب» لتهديد الأب، ونقطة «أسئلة كأسئلة القاضي» لأسئلة إبراهيم.', 'أعد تشغيل الآيات واطلب رفع بطاقة «الأب» أو «إبراهيم» عند كل جملة.', 'تهديد الأب يُقرأ مرة بهدوء ويُفهم، ولا يُمثَّل ولا يُكرَّر.'],
    differentiation: { strugglingLearners: 'قدّم الجدول نصف مملوء وإطارات مشكولة: «يسأل ____ لـ____ِ ____»، «يسأل ____ لكي ____َ ____»، «قد ____ُ ____»، «لم يمنعه ____ من ____».', fastFinishers: 'اكتب تشبيهًا ثلاثيًّا جديدًا («كما… أو كما…، كان…») يشرح طريقة معلّم جيد في طرح الأسئلة، وحدّد الغاية في كل طرف.' },
    formativeAssessment: ['يميّز التهديد من الالتزام والرجاء في الآيات.', 'يعبّر عن الغاية بالمصدر وبالفعل المنصوب بإعراب صحيح.', 'يستعمل «قد + مضارع» للاحتمال و«منعه من» في سياق جديد.'],
    expectedResponses: ['هدّد الأب إبراهيم وطرده، فردّ إبراهيم بالسلام ووعد بأن يستغفر له واعتزل ما يعبدون، ولم يمنعه سلوك أبيه القاسي من حمل رسالته، فذهب إلى المدينة ليجادل الناس وهو يعلم أنه قد يواجه عواقب سلبية، وكان يسألهم ليُظهر حقيقة موقفهم كما يسأل الطبيب والقاضي لكشف الحقيقة.'],
    transferTask: 'اكتب ثلاث جمل عن هدف تريد تحقيقه هذا العام: جملة بـ«قد + مضارع» لصعوبة محتملة، وجملة بـ«سـ» لالتزامك، وجملة غاية بالمصدر.',
    teacherReflection: 'هل ميّز المتعلمون بين الاحتمال والتحقيق في «قد» بأنفسهم؟ وهل فهموا ردّ إبراهيم على التهديد بوصفه ثباتًا لا ضعفًا؟',
    assessmentTools: { rubric: ['التهديد والالتزام', 'الغاية بطريقتين', '«قد» والاحتمال', 'التشبيه والفقرة'], exitTicket: ['اكتب جملة بـ«قد + مضارع» وأخرى بـ«قد + ماضٍ» عن الموضوع نفسه، واشرح الفرق بكلمة واحدة لكل جملة.'] },
