    afterReading: ['أنجز التحدي السريع مع الرجوع إلى قوس المشاعر.', 'التركيز اللغوي: معنى «ما دام» (النشاط 1)، ثم التحويل إلى «في أثناء» و«طالما» و«وإنّما» (النشاط 2)، ثم تصحيح الجرّ والنعت والنصب (النشاط 3).', 'اكتب فقرة النشاط 4 من القلق إلى الفهم.'],
    lessonPlan: '0–4 تهيئة: جملة «لن أخاف ما دام أخي معي»، والثنائيات تشرح معناها وتكتب جملة مثلها؛ 4–10 استماع ثم قراءة صامتة مع سؤالي الاستماع؛ 10–16 قوس المشاعر: في ثنائيات يضع المتعلمون عبارات على نقاط القوس الخمس، ويعدّون ما ينقص الوادي من وصفه؛ 16–19 قراءة جهرية مضبوطة للحوار ولجملة النفي المتراكم، مع ترقيق لفظ الجلالة وتفخيمه؛ 19–22 التحدي السريع؛ 22–31 التركيز اللغوي: النشاط 1 اكتشافًا جماعيًّا (هل «ما» هنا نفي؟)، والنشاط 2 في ثنائيات، والنشاط 3 فرديًّا مع تعليل كل تصحيح بكلمة (معطوف / نعت / منصوب)؛ 31–38 استعمال: فقرة النشاط 4 عن أول يوم في مدرسة جديدة أو سكن طلابي، تبدأ بثلاثة عناصر منفية وتنتهي بفهم جديد، وفيها «ما دام» و«لم يكن… بل…»؛ 38–40 بطاقة الخروج',
    discussionPoints: ['ماذا يضيف وصف الوادي المنفي المتراكم إلى فهمنا لموقف هاجر؟', 'كيف تغيّر شعور هاجر بعد جواب إبراهيم؟ وما الذي فهمته؟', 'كيف ينتهي الفصل؟ وماذا نتوقع أن يأتي بعد «ربّنا…» في الفصل التالي؟'],
    interactiveTips: ['استخدم نقطة «في رعاية الله» لترك الأسرة في رعاية الله، ونقطة «سؤال هاجر» لسؤال هاجر.', 'أعد تشغيل الحوار واطلب تحديد لحظة التحوّل من القلق إلى الراحة.', 'لا يُمثَّل الحوار بين هاجر وإبراهيم ولا يُرسم؛ ونبّه إلى أن الدعاء يكتمل في الفصل التالي.'],
    differentiation: { strugglingLearners: 'قدّم قوس المشاعر مع العبارات مقطّعة، وإطارات مشكولة: «لا يوجد ____ٌ ولا ____ٌ ولا ____ٌ»، «لن ____َ ما دام ____ معنا»، «لم يكن ____، بل ____».', fastFinishers: 'اكتب جملة هاجر «لن نضلّ ما دام الله معنا» بثلاث صياغات شرطية («طالما»، «ما دام»، «إذا كان») واشرح أيّها أقوى في الدلالة على الاستمرار.' },
